/* List Management layout matched to the reference's two-panel control screen. */
listsPage=function(){
 let models=listName==='Vehicle Models',values=models?(db.vehicleModels||[]):db.lists[listName]||[],total=Object.keys(db.lists).length;
 return `<section class="list-management"><div class="list-management-title"><div><h2>Dropdown List Management <span>Master Control</span></h2><p>Manage, customize, add &amp; edit dropdown options across the entire garage system in real time.</p></div><div class="list-management-top-actions"><span class="list-system-tag">SYSTEM DROPDOWNS <b>${total} LISTS</b></span><button type="button" class="btn list-sync-save" id="syncAllDropdownLists">↻ &nbsp;Sync All</button></div></div><div class="listlayout list-management-grid"><aside class="listselector-card"><div class="listselector-heading"><b>System Dropdowns</b><span>${total} Lists</span></div><div class="listselector">${Object.keys(db.lists).map(key=>`<button class="${key===listName?'active':''}" data-list="${esc(key)}"><span>${esc(sharedListLabel(key))}</span><b>${(db.lists[key]||[]).length}</b></button>`).join('')}</div></aside><section class="panel list-editor-card"><div class="panelhead list-editor-head"><div><h2>${esc(sharedListLabel(listName))}</h2><p>${models?'Vehicle model choices for each two-wheeler make':'Used in linked forms and filters'}</p></div><span class="list-count">${values.length} Options</span></div><div class="panelbody"><form id="managedListForm" class="list-add-form">${models?`<select id="managedModelMake" required aria-label="Vehicle make for model"><option value="">Select Vehicle Make</option>${opts(partVehicleMakes(),managedModelMake)}</select>`:''}<label class="list-add-input"><span aria-hidden="true">＋</span><input name="option" required placeholder="Type new option name (e.g. ${listName==='Vehicle Brands'?'Honda':models?'Activa':'Option name'})" aria-label="New list option"></label><button class="btn" type="submit">＋ &nbsp;Add Option</button></form><input id="managedListSearch" class="list-search" type="search" aria-label="Search options" placeholder="⌕  Search options in this list…" value="${esc(managedListSearch)}"><p class="list-edit-hint">ⓘ &nbsp;Click <b>✎</b> to rename or <b>×</b> to remove option.</p><div id="managedListRows" class="listoption-grid">${values.map((value,i)=>{let text=models?value.make+' — '+value.model:value;return `<div class="listoption" data-list-text="${esc(text.toLowerCase())}" ${text.toLowerCase().includes(managedListSearch.toLowerCase())?'':'hidden'}><span>${esc(text)}</span><div><button type="button" class="btn secondary small" data-managed-rename="${i}" aria-label="Rename ${esc(text)}" title="Rename option">✎</button><button type="button" class="btn danger small" data-managed-remove="${i}" aria-label="Remove ${esc(text)}" title="Delete option">×</button></div></div>`}).join('')}</div><div class="list-live-sync"><span class="list-sync-check">✓</span><div><b>Automatic Live Sync:</b> All options added, edited, or deleted here are immediately reflected in form dropdowns across the system without page refresh.<small>LIVE CONNECTED</small></div></div></div></section></div></section>`
};
const listLayoutRenderBeforeParity=render;
render=function(){listLayoutRenderBeforeParity();if(page!=='lists')return;const old=$('#syncAllDropdownLists');if(old){old.innerHTML='↻ &nbsp;Sync &amp; Save';old.className='btn list-sync-save'} };
render();

